use Zwii\Cms\Helper; trait Tools { public function getUrl($key = null) { return self::resolveModuleInstanceUrl($this->url, $key); } public static function makeThumb($src, $dest = null, $desired_width = 200) { if (!file_exists($src)) { error_log("Fichier source introuvable: $src"); return false; } if ($dest === null) { $srcInfo = pathinfo($src); $destDir = str_replace('source', 'thumb', $srcInfo['dirname']); if (!is_dir($destDir) && !mkdir($destDir, 0755, true)) { error_log("Impossible de créer le répertoire de destination: $destDir"); return false; } $dest = $destDir . '/' . self::THUMBS_SEPARATOR . strtolower($srcInfo['basename']); } $fileInfo = pathinfo($dest); $extension = strtolower($fileInfo['extension'] ?? ''); $mime_type = mime_content_type($src); if ($extension === 'svg' || $mime_type === 'image/svg+xml') { return copy($src, $dest) ? $dest : false; } $source_image = null; try { switch (strtolower(pathinfo($src, PATHINFO_EXTENSION))) { case 'jpeg': case 'jpg': $source_image = imagecreatefromjpeg($src); break; case 'png': $source_image = imagecreatefrompng($src); break; case 'gif': $source_image = imagecreatefromgif($src); break; case 'webp': $source_image = imagecreatefromwebp($src); break; case 'avif': if (function_exists('imagecreatefromavif')) { $source_image = imagecreatefromavif($src); } break; default: error_log("Format d'image non supporté: $src"); return false; } if (!$source_image) { error_log("Impossible de charger l'image source: $src"); return false; } $width = imagesx($source_image); $height = imagesy($source_image); $desired_height = floor($height * ($desired_width / $width)); $virtual_image = imagecreatetruecolor($desired_width, $desired_height); if (in_array($extension, ['png', 'gif'])) { imagealphablending($virtual_image, false); imagesavealpha($virtual_image, true); $transparent = imagecolorallocatealpha($virtual_image, 255, 255, 255, 127); imagefilledrectangle($virtual_image, 0, 0, $desired_width, $desired_height, $transparent); } imagecopyresampled( $virtual_image, $source_image, 0, 0, 0, 0, $desired_width, $desired_height, $width, $height ); $result = false; switch ($mime_type) { case 'image/jpeg': case 'image/jpg': $result = imagejpeg($virtual_image, $dest, 85); break; case 'image/png': $result = imagepng($virtual_image, $dest, 8); break; case 'image/gif': $result = imagegif($virtual_image, $dest); break; case 'image/webp': $result = imagewebp($virtual_image, $dest, 85); break; case 'image/avif': if (function_exists('imageavif')) { $result = imageavif($virtual_image, $dest, 60); } break; } if (PHP_VERSION_ID < 80000) { imagedestroy($virtual_image); imagedestroy($source_image); } if ($result && file_exists($dest)) { return $dest; } error_log("Échec de la sauvegarde de la miniature: $dest"); return false; } catch (Exception $e) { if (PHP_VERSION_ID < 80000) { if (isset($source_image) && (is_resource($source_image) || $source_image instanceof GdImage)) { imagedestroy($source_image); } if (isset($virtual_image) && (is_resource($virtual_image) || $virtual_image instanceof GdImage)) { imagedestroy($virtual_image); } } error_log("Erreur lors de la création de la miniature: " . $e->getMessage()); return false; } } public static function getThumb($sourcePath, $prefix = self::THUMBS_SEPARATOR) { if (empty($sourcePath)) { return ''; } $pathInfo = pathinfo($sourcePath); $dirName = str_replace('source', 'thumb', $pathInfo['dirname']); $filename = $pathInfo['filename']; $extension = $pathInfo['extension'] ?? ''; $newFilename = $prefix . $filename . ($extension ? '.' . $extension : ''); return $dirName . '/' . $newFilename; } public function deleteDir($path) { foreach (new DirectoryIterator($path) as $item) { if ($item->isFile()) @unlink($item->getRealPath()); if (!$item->isDot() && $item->isDir()) $this->deleteDir($item->getRealPath()); } return (rmdir($path)); } public function copyDir($src, $dst) { $dir = opendir($src); if ($dir === false) { return false; } if (!is_dir($dst)) { $success = mkdir($dst, 0755, true); } else { $success = true; } while (($file = readdir($dir)) !== false) { if ($file === '.' || $file === '..') { continue; } if (is_dir($src . '/' . $file)) { $s = $this->copyDir($src . '/' . $file, $dst . '/' . $file); if ($s === false) { $success = false; } } else { $s = copy($src . '/' . $file, $dst . '/' . $file); if ($s === false) { $success = false; } } } closedir($dir); return $success; } public function recursive_array_replace($find, $replace, $array, &$count) { if ($find === '' || $find === null) { return $array; } if (!is_array($array)) { return str_replace($find, $replace, $array, $count); } $newArray = []; foreach ($array as $key => $value) { $c = 0; $newArray[$key] = $this->recursive_array_replace($find, $replace, $value, $c); $count += $c; } return $newArray; } public function makeZip($fileName, $folder, $filter = []) { $zip = new ZipArchive(); $zip->open($fileName, ZipArchive::CREATE | ZipArchive::OVERWRITE); $files = new RecursiveIteratorIterator( new RecursiveCallbackFilterIterator( new RecursiveDirectoryIterator( $folder, RecursiveDirectoryIterator::SKIP_DOTS ), function ($fileInfo, $key, $iterator) use ($filter) { return $fileInfo->isFile() || !in_array($fileInfo->getBaseName(), $filter); } ) ); foreach ($files as $name => $file) { if (!$file->isDir()) { $filePath = $file->getRealPath(); $relativePath = substr($filePath, strlen(realpath($folder)) + 1); $zip->addFile($filePath, str_replace('\\', '/', $relativePath)); } } $zip->close(); } public function signature($userId) { switch ($this->getData(['user', $userId, 'signature'])) { case 1: return $userId; case 2: return $this->getData(['user', $userId, 'pseudo']); case 3: return $this->getData(['user', $userId, 'firstname']) . ' ' . $this->getData(['user', $userId, 'lastname']); case 4: return $this->getData(['user', $userId, 'lastname']) . ' ' . $this->getData(['user', $userId, 'firstname']); default: return $this->getData(['user', $userId, 'firstname']); } } public function getRelativePath($path) { return str_replace(Helper::baseUrl(false), '', $path); } public function getSiteContentQueryParam() { if (file_exists(self::DATA_DIR . self::$siteContent . '/.default')) { return ''; } $installedLangCount = 0; foreach (self::$languages as $key => $value) { if (is_dir(self::DATA_DIR . $key)) { $installedLangCount++; if ($installedLangCount > 1) { $separator = Helper::checkRewrite() ? '?' : '&'; return $separator . 'l=' . self::$siteContent; } } } return ''; } public function getPageEditUrl() { return Helper::baseUrl() . 'page/edit/' . $this->getPageId() . $this->getSiteContentQueryParam(); } }
